import { ref, get, onValue, push, set, remove  } from "firebase/database";

import React, { useEffect, useMemo, useState } from "react";
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer, Legend } from "recharts";
import { CalendarPlus, Trash2, Trophy, BarChart2 } from "lucide-react";
import { db } from "./firebase";





const uid = () => Math.random().toString(36).slice(2, 10);
const COLORS = ["#2E8B57", "#3498DB", "#F4D03F", "#E67E22", "#9B59B6", "#E74C3C", "#1ABC9C"];
const POINTS_FOR_PLACE = (p: number) => (p === 1 ? 10 : p === 2 ? 6 : p === 3 ? 4 : p <= 10 ? 2 : 1);
const medal = (i: number) => (i === 0 ? "🥇" : i === 1 ? "🥈" : i === 2 ? "🥉" : "");
const MIN_EVENTS = 6;
const defaultNames = ["Robert", "Andy", "Hector", "Rodmy", "Yoe", "Yuri", "Omar"];

export default function NLHNSeriesLeaderboard() {
	useEffect(() => {
  const testConnection = async () => {
    try {
      await get(ref(db, "/"));
      console.log("✅ Firebase connected successfully");
    } catch (error) {
      console.error("❌ Firebase connection error:", error);
    }
  };
  testConnection();
}, []);
useEffect(() => {
  const tournamentsRef = ref(db, "series/default/tournaments");
  const unsubscribe = onValue(tournamentsRef, (snapshot) => {
    const data = snapshot.val();
    if (data) {
      const tournaments = Object.entries(data).map(([id, t]: any) => ({
        id,
        ...t,
      }));
      setSeriesList([{ id: "default", name: "NLHN Series", tournaments }]);
      console.log("✅ Tournaments loaded from Firebase:", tournaments);
    } else {
      console.log("⚠️ No tournaments found in Firebase yet.");
      setSeriesList([{ id: "default", name: "NLHN Series", tournaments: [] }]);
    }
  });

  return () => unsubscribe(); // cleanup listener
}, []);

	
  const [seriesList, setSeriesList] = useState([{ id: uid(), name: "NLHN Series", tournaments: [] as any[] }]);
  const [activeSeriesIdx, setActiveSeriesIdx] = useState(0);
  const [tab, setTab] = useState<'tournaments' | 'leaderboard'>('tournaments');
  const [addNames, setAddNames] = useState<Record<string, string>>({});
  const activeSeries = seriesList[activeSeriesIdx];

const addTournament = async () => {
  try {
    const newRef = push(ref(db, "series/default/tournaments"));
    const newT = {
      id: newRef.key,
      name: `Tournament ${activeSeries.tournaments.length + 1}`,
      results: Object.fromEntries(
        defaultNames.map((name) => [
          uid(),
          { name, buyIn: 0, cashOut: 0, place: 0 },
        ])
      ),
      createdAt: Date.now(),
    };
    await set(newRef, newT);
    console.log("✅ Tournament added to Firebase:", newT);
  } catch (error) {
    console.error("❌ Error adding tournament:", error);
  }
};




const updateField = async (
  tId: string,
  pid: string,
  field: "name" | "buyIn" | "cashOut" | "place",
  value: string
) => {
  // Local update (so UI feels instant)
  setSeriesList((prev) => {
    const copy = [...prev];
    const s = { ...copy[activeSeriesIdx] };
    const tIdx = s.tournaments.findIndex((t: any) => t.id === tId);
    if (tIdx === -1) return prev;
    const t = { ...s.tournaments[tIdx] };
    const player = t.results[pid];
    t.results[pid] = {
      ...player,
      [field]: field === "name" ? value : Number(value) || 0,
    };
    s.tournaments[tIdx] = t;
    copy[activeSeriesIdx] = s;
    return copy;
  });

  // Firebase update
  try {
    const cleanValue = field === "name" ? value : Number(value) || 0;
    const path = `series/default/tournaments/${tId}/results/${pid}/${field}`;
    console.log("🛰 Writing to:", path, "=", cleanValue);
    await set(ref(db, path), cleanValue);
    console.log("✅ Firebase updated");
  } catch (err) {
    console.error("❌ Firebase update error:", err);
  }
};


  const addPlayerWithName = (tId: string) => {
    const name = (addNames[tId] || "").trim();
    if (!name) return;
    setSeriesList(prev => {
      const copy = [...prev];
      const s = { ...copy[activeSeriesIdx] };
      const tIdx = s.tournaments.findIndex((t: any) => t.id === tId);
      if (tIdx === -1) return prev;
      const t = { ...s.tournaments[tIdx] };
      t.results[uid()] = { name, buyIn: 0, cashOut: 0, place: 0 };
      s.tournaments[tIdx] = t;
      copy[activeSeriesIdx] = s;
      return copy;
    });
    setAddNames(prev => ({ ...prev, [tId]: "" }));
  };

const removePlayer = async (tId: string, pid: string) => {
  // update UI instantly
  setSeriesList(prev => {
    const copy = [...prev];
    const s = { ...copy[activeSeriesIdx] };
    const tIdx = s.tournaments.findIndex((t: any) => t.id === tId);
    if (tIdx === -1) return prev;
    const t = { ...s.tournaments[tIdx] };
    const { [pid]: _removed, ...rest } = t.results;
    t.results = rest;
    s.tournaments[tIdx] = t;
    copy[activeSeriesIdx] = s;
    return copy;
  });

  // also remove from Firebase
  try {
    const path = `series/default/tournaments/${tId}/results/${pid}`;
    await remove(ref(db, path));
    console.log(`🗑️ Removed player ${pid} from Firebase`);
  } catch (err) {
    console.error("❌ Firebase remove error:", err);
  }
};

  const summary = useMemo(() => {
    const agg = new Map<string, any>();
    for (const t of activeSeries.tournaments) {
      for (const [_pid, r] of Object.entries(t.results)) {
        const rr: any = r;
        if (!agg.has(rr.name)) agg.set(rr.name, { name: rr.name, buyIn: 0, cashOut: 0, events: 0, top3: 0, firsts: 0, seconds: 0, thirds: 0, pts: 0 });
        const a = agg.get(rr.name);
        a.buyIn += rr.buyIn; a.cashOut += rr.cashOut; a.events++;
        if (rr.place === 1) a.firsts++;
        if (rr.place === 2) a.seconds++;
        if (rr.place === 3) a.thirds++;
        if (rr.place && rr.place <= 3) a.top3++;
        a.pts += POINTS_FOR_PLACE(rr.place);
      }
    }
    const rows = Array.from(agg.values()).map((v: any) => {
      const profit = v.cashOut - v.buyIn;
      const roi = v.buyIn ? (v.cashOut - v.buyIn) / v.buyIn : 0;
      const itm = v.events ? v.top3 / v.events : 0;
      const eff = v.events ? v.pts / v.events : 0;
      const score = v.pts * eff;
      return { ...v, profit, roi, itm, eff, score, eligible: v.events >= MIN_EVENTS };
    }).sort((a: any, b: any) => b.score - a.score);
    return rows;
  }, [activeSeries]);

  const chartData = summary.map((r: any, i: number) => ({ name: r.name, value: r.cashOut, fill: COLORS[i % COLORS.length] }));

  return (
      <div className="flex justify-center bg-gray-100 min-h-screen">
    <div className="w-full max-w-3xl bg-white shadow-lg p-6 rounded-xl">
	


      <h1 className="text-2xl font-bold mb-4">NLHN Series</h1>
      <div className="flex gap-3 mb-6">
        <button onClick={() => setTab('tournaments')} className={`px-3 py-1 rounded ${tab==='tournaments'?'bg-emerald-600 text-white':'bg-white border'}`}>Tournaments</button>
        <button onClick={() => setTab('leaderboard')} className={`px-3 py-1 rounded ${tab==='leaderboard'?'bg-emerald-600 text-white':'bg-white border'}`}>Leaderboard</button>
      </div>

      {tab==='tournaments' && (
        <div>
          <button onClick={addTournament} className="bg-indigo-600 text-white px-3 py-2 rounded mb-4 flex items-center gap-2"><CalendarPlus className="w-4 h-4"/> Add Tournament</button>
          {activeSeries.tournaments.map(t => (
            <div key={t.id} className="bg-white rounded shadow p-4 mb-4">
              <div className="flex justify-between items-center mb-2">
                <h2 className="text-lg font-semibold">{t.name}</h2>
                <div className="flex items-center gap-2">
                  <input className="border rounded px-2 py-1 text-sm" placeholder="New player name" value={addNames[t.id] || ""} onChange={(e)=>setAddNames(prev=>({ ...prev, [t.id]: e.target.value }))}/>
                  <button onClick={() => addPlayerWithName(t.id)} className="text-sm bg-blue-600 text-white px-2 py-1 rounded">+ Add Player</button>
                </div>
              </div>
              <table className="w-full text-sm border">
                <thead className="bg-neutral-100"><tr><th>Player</th><th>Buy-in</th><th>Cash-out</th><th>Place</th><th></th></tr></thead>
                <tbody>
                  {Object.entries(t.results).map(([pid, r]) => (
                    <tr key={pid} className="even:bg-neutral-50">
                      <td><input type="text" className="border rounded px-1 w-40" value={(r as any).name} onChange={e=>updateField(t.id,pid,'name',e.target.value)} /></td>
                      <td><input type="number" className="border rounded w-24 px-1" value={(r as any).buyIn} onChange={e=>updateField(t.id,pid,'buyIn',e.target.value)} /></td>
                      <td><input type="number" className="border rounded w-24 px-1" value={(r as any).cashOut} onChange={e=>updateField(t.id,pid,'cashOut',e.target.value)} /></td>
                      <td><input type="number" className="border rounded w-20 px-1" value={(r as any).place} onChange={e=>updateField(t.id,pid,'place',e.target.value)} /></td>
                      <td><button onClick={()=>removePlayer(t.id,pid)} className="text-red-600 flex items-center gap-1"><Trash2 className="w-4 h-4"/>Del</button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ))}
        </div>
      )}

     {tab === 'leaderboard' && (
  <div className="flex flex-col gap-6">
    {/* Leaderboard Table */}
    <div className="bg-white rounded shadow p-4 overflow-auto">
      <h2 className="text-lg font-semibold mb-3 flex items-center gap-2">
        <Trophy className="w-5 h-5" /> Leaderboard
      </h2>
      <table className="w-full text-sm">
        <thead className="bg-emerald-700 text-white">
          <tr>
            <th>Player</th>
            <th>Events</th>
            <th>1st</th>
            <th>2nd</th>
            <th>3rd</th>
            <th>Buy-in</th>
            <th>Cash-out</th>
            <th>Profit</th>
            <th>ROI%</th>
            <th>ITM%</th>
            <th>Eff</th>
            <th>Score</th>
            <th>Elig</th>
          </tr>
        </thead>
        <tbody>
          {summary.map((r, i) => (
            <tr key={r.name} className="even:bg-neutral-50">
              <td>{medal(i)} {r.name}</td>
              <td>{r.events}</td>
              <td>{r.firsts}</td>
              <td>{r.seconds}</td>
              <td>{r.thirds}</td>
              <td>${r.buyIn.toFixed(2)}</td>
              <td>${r.cashOut.toFixed(2)}</td>
              <td>${r.profit.toFixed(2)}</td>
              <td>{(r.roi * 100).toFixed(1)}%</td>
              <td>{(r.itm * 100).toFixed(1)}%</td>
              <td>{r.eff.toFixed(2)}</td>
              <td>{r.score.toFixed(2)}</td>
              <td>{r.eligible ? '✅' : '❌'}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>

    {/* Pie Chart Below Leaderboard */}
    <div className="bg-white rounded shadow p-4">
      <h2 className="text-lg font-semibold mb-3 flex items-center gap-2">
        <BarChart2 className="w-5 h-5" /> Cash-out Distribution
      </h2>
      <div className="h-72">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={chartData}
              dataKey="value"
              nameKey="name"
              innerRadius={60}
              outerRadius={110}
              paddingAngle={3}
            >
              {chartData.map((c, i) => (
                <Cell key={i} fill={c.fill} />
              ))}
            </Pie>
            <Tooltip formatter={(v: any) => `$${v}`} />
            <Legend />
          </PieChart>
        </ResponsiveContainer>
      </div>
    </div>
  </div>
)}

    </div>
   </div> 
 
  );
}
